func (d *DockerCompose) Settings(settingsFile, envFile string, connections, variables, pools, export, envExport, logs bool) error {
	// setup bools
	if !connections && !variables && !pools {
		connections = true
		variables = true
		pools = true
	}

	if export {
		return d.ExportAirflowSettings(settingsFile, envFile, connections, variables, pools, envExport, logs)
	}
	if !envExport {
		return d.ImportAirflowSettings(settingsFile, connections, variables, pools, logs)
	}

	_, _, err := d.getAirflowSettingsConfig(settingsFile)
	return err
}

func (d *DockerCompose) ImportAirflowSettings(settingsFile string, connections, variables, pools, logs bool) error {
	containerID, airflowDockerVersion, err := d.getAirflowSettingsConfig(settingsFile)
	if err != nil {
		return err
	}

	err = initSettings(containerID, settingsFile, airflowDockerVersion, connections, variables, pools, logs)
	if err != nil {
		return err
	}
	fmt.Println("\nAirflow objects created from settings file")
	return nil
}

func (d *DockerCompose) ExportAirflowSettings(settingsFile, envFile string, connections, variables, pools, envExport, logs bool) error {
	containerID, airflowDockerVersion, err := d.getAirflowSettingsConfig(settingsFile)
	if err != nil {
		return err
	}

	if envExport {
		err = envExportSettings(containerID, envFile, airflowDockerVersion, connections, variables, logs)
		if err != nil {
			return err
		}
		fmt.Println("\nAirflow objects exported to env file")
		return nil
	}

	err = exportSettings(containerID, settingsFile, airflowDockerVersion, connections, variables, pools, logs)
	if err != nil {
		return err
	}
	fmt.Println("\nAirflow objects exported to settings file")
	return nil
}

func (d *DockerCompose) getAirflowSettingsConfig(settingsFile string) (string, uint64, error) {
	// Get project containers
	psInfo, err := d.composeService.Ps(context.Background(), d.projectName, api.PsOptions{
		All: true,
	})
	if err != nil {
		return "", 0, errors.Wrap(err, composeCreateErrMsg)
	}
	if len(psInfo) == 0 {
		return "", 0, errors.New("project not running, run docker dev start to start project")
	}

	imageLabels, err := d.imageHandler.ListLabels()
	if err != nil {
		return "", 0, err
	}

	airflowDockerVersion := defaultAirflowVersion
	airflowVersion, ok := imageLabels[airflowVersionLabelName]
	if ok {
		if version := semver.MustParse(airflowVersion); version != nil {
			airflowDockerVersion = version.Major()
		}
	}
	fileState, err := fileutil.Exists(settingsFile, nil)
	if err != nil {
		return "", 0, errors.Wrap(err, errSettingsPath)
	}
	if !fileState {
		return "", 0, errors.New("file specified does not exist")
	}

	containerID, err := d.getWebServerContainerID()
	if err != nil {
		return "", 0, err
	}
	return containerID, airflowDockerVersion, nil
}

